    @Test
    fun `kotlin切帧逐字对拍PC基准`() {
        for (v in vectors) {
            val (frames, tail) = FrameSplitter.extract(hexBytes(v.streamHex), v.direction)
            assertEquals("帧数 ${v.label}", v.expectedFramesHex.size, frames.size)
            v.expectedFramesHex.forEachIndexed { idx, exp ->
                assertArrayEquals("帧#$idx ${v.label}", hexBytes(exp), frames[idx].body)
            }
            assertArrayEquals("余留 ${v.label}", hexBytes(v.expectedTailHex), tail)
        }
    }

    private fun hexBytes(hex: String): ByteArray =
        hex.chunked(2).map { ((it.toInt(16)) and 0xff).toByte() }.toByteArray()
}
